import pygit2
import json
import os
import re

repo_path = "/workdir/data"
repo = pygit2.Repository(repo_path)

# ==================== TASK 1: Repo Status ====================
head_commits = set()
for commit in repo.walk(repo.head.peel().id):
    head_commits.add(commit.id)

all_commits = set()
obj_dir = os.path.join(repo_path, ".git", "objects")
for root, dirs, files in os.walk(obj_dir):
    for f in files:
        if f.startswith("pack") or f.startswith("info"):
            continue
        hexsha = os.path.basename(root) + f
        try:
            obj = repo[hexsha]
            if isinstance(obj, pygit2.Commit):
                all_commits.add(obj.id)
        except:
            pass

dangling = all_commits - head_commits

repo_status = {
    "total_commits": len(all_commits),
    "current_branch_commits": len(head_commits),
    "dangling_commits": len(dangling)
}
with open("/workdir/repo_status.json", "w") as f:
    json.dump(repo_status, f, indent=2)
print("repo_status.json:", json.dumps(repo_status, indent=2))

# ==================== TASK 2: Security Audit ====================
# Scan all blobs for secrets
all_blobs = {}
obj_dir = os.path.join(repo_path, ".git", "objects")
for root, dirs, files in os.walk(obj_dir):
    for f in files:
        if f.startswith("pack") or f.startswith("info"):
            continue
        hexsha = os.path.basename(root) + f
        try:
            obj = repo[hexsha]
            if isinstance(obj, pygit2.Blob):
                all_blobs[hexsha] = obj.read().decode()
        except:
            pass

password_pattern = re.compile(r'(?:password|passwd|pwd|secret|key)\s*[=:]\s*["\']?([^"\'\s]+)', re.IGNORECASE)
sensitive_files = []
hardcoded_passwords = set()

# Check all blobs
for blob_sha, content in all_blobs.items():
    matches = password_pattern.findall(content)
    if matches:
        # Find the filename for this blob
        for commit_oid in all_commits:
            commit = repo[commit_oid]
            tree = commit.tree
            for entry in tree:
                try:
                    if entry.id == blob_sha:
                        if entry.name not in sensitive_files:
                            sensitive_files.append(entry.name)
                        for m in matches:
                            hardcoded_passwords.add(m)
                except:
                    pass

# Also check working directory files
for root, dirs, files in os.walk(repo_path):
    if ".git" in root:
        continue
    for fname in files:
        fpath = os.path.join(root, fname)
        try:
            content = open(fpath).read()
            matches = password_pattern.findall(content)
            if matches and fname not in sensitive_files:
                sensitive_files.append(fname)
                for m in matches:
                    hardcoded_passwords.add(m)
        except:
            pass

security_audit = {
    "exposed_credentials": len(hardcoded_passwords),
    "sensitive_files": sorted(sensitive_files),
    "hardcoded_passwords": sorted(list(hardcoded_passwords))
}
with open("/workdir/security_audit.json", "w") as f:
    json.dump(security_audit, f, indent=2)
print("\nsecurity_audit.json:", json.dumps(security_audit, indent=2))

# ==================== TASK 3: Recovery Report ====================
# Find deleted files by comparing trees
deleted_files = []
head_tree = repo.head.peel().tree
dangling_commit = repo[list(dangling)[0]]
dangling_tree = dangling_commit.tree

# Files in dangling but not in HEAD
dangling_files = {e.name for e in dangling_tree}
head_files = {e.name for e in head_tree}
deleted_files = sorted(list(dangling_files - head_files))

# Also check intermediate commits for deleted files
for commit_oid in head_commits:
    commit = repo[commit_oid]
    if len(commit.parents) > 0:
        parent_tree = commit.parents[0].tree
        curr_tree = commit.tree
        parent_files = {e.name for e in parent_tree}
        curr_files = {e.name for e in curr_tree}
        newly_deleted = parent_files - curr_files
        for f in newly_deleted:
            if f not in deleted_files:
                deleted_files.append(f)

# Find suspicious author (the one with dangling commit)
suspicious_author = repo[list(dangling)[0]].author.email

recovery_report = {
    "dangling_commit_sha": str(list(dangling)[0]),
    "deleted_files": sorted(deleted_files),
    "suspicious_author": suspicious_author
}
with open("/workdir/recovery_report.json", "w") as f:
    json.dump(recovery_report, f, indent=2)
print("\nrecovery_report.json:", json.dumps(recovery_report, indent=2))
PYEOF"}

